import math


def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()


def build_agent(sandbox):
    return sandbox.get_seeker_body()


def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0,
            'last_ty': 0.0,
            'tvx': 0.0,
            'tvy': 0.0,
            'cooldown_remaining': 0
        }
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Estimate target velocity using history
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Determine desired heading
    target_speed = math.hypot(state['tvx'], state['tvy'])
    if target_speed >= 0.15:
        # Align with target's velocity direction
        desired_angle = math.atan2(state['tvy'], state['tvx'])
    else:
        # Align with seeker-to-target direction
        desired_angle = math.atan2(ty - sy, tx - sx)

    # Current heading
    current_angle = sandbox.get_seeker_heading()

    # Calculate angular velocity to rotate toward desired heading
    delta_angle = desired_angle - current_angle
    if delta_angle > 0.12:
        angular_velocity = 0.12
    elif delta_angle < -0.12:
        angular_velocity = -0.12
    else:
        angular_velocity = delta_angle

    # Apply angular velocity to rotate seeker
    seeker = sandbox.get_seeker_body()
    seeker.angularVelocity = angular_velocity

    # Calculate desired position
    if step_count < 110:
        gx, gy = 11.95, 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        gx = 13.1 if (step_count // 120) % 2 == 0 else 13.5
        gy = 1.35

    # Calculate force vector
    if in_slot:
        fx = 300.0 * (gx - sx) + 60.0 * (state['tvx'] - svx)
        fy = 300.0 * (gy - sy) + 60.0 * (state['tvy'] - svy)
    else:
        fx = 300.0 * (gx - sx) - 60.0 * svx
        fy = 180.0 * (gy - sy) - 45.0 * svy

    # Check for cooldown
    mag = math.sqrt(fx * fx + fy * fy)
    if mag > 65.0 and state['cooldown_remaining'] == 0:
        state['cooldown_remaining'] = 250

    # Clamp thrust based on cooldown
    if state['cooldown_remaining'] > 0:
        max_thrust = 10.0
    else:
        max_thrust = 119.0

    if mag > max_thrust:
        fx, fy = fx * max_thrust / mag, fy * max_thrust / mag

    # Apply force
    sandbox.apply_seeker_force(fx, fy)

    # Update cooldown timer
    if state['cooldown_remaining'] > 0:
        state['cooldown_remaining'] -= 1
